INSERT IGNORE INTO `quest_offer_reward` (`ID`,`Emote1`,`Emote2`,`Emote3`,`Emote4`,`EmoteDelay1`,`EmoteDelay2`,`EmoteDelay3`,`EmoteDelay4`,`RewardText`,`VerifiedBuild`) VALUES
(96607,273,273,0,0,0,0,0,0,'Мы изучили основы, а теперь иди поучись ремеслу у наставников в деревне поблизости. Они даже могут показать, как обустроить лагерь в соответствии с твоей новой профессией.',70450),
(96656,273,273,0,0,0,0,0,0,'Я не с Алым орденом, если ты еще не $gдогадался:догадалась;. Я простая искательница приключений, которая ненадолго остановилась тут перед следующим путешествием в дикие края.\r\n\r\nА ты на вид $gтакой же искатель:такая же искательница; приключений, как я. Не хочешь поучиться премудростям походной жизни?',70450),
(96658,273,273,0,0,0,0,0,0,'С этим ты сможешь разбить лагерь где угодно. Пока ты $gосвоил:освоила; только азы, так что особенно обставить лагерь не получится.\r\n\r\nУчись – и со временем научишься разжигать огонь пожарче и делать разные интересные вещи.\r\n\r\nЕще ты можешь научиться создавать разные полезные вещи в лагере – поговори с другими наставниками профессий, в которых хоть немного разбираешься.',70450);
