UPDATE `quest_offer_reward_locale` SET `RewardText` = 'Тем, кто пережил смерть, боль не в новинку, и поэтому Отрекшиеся к ней особенно устойчивы. Боль также очищает – пусть она станет для тебя знаком почета и доказательством того, что ты не $gоставил:оставила; служение Свету, несмотря на нынешние обстоятельства.\r\n\r\nБереги себя и следуй путем Света, паладин.', `VerifiedBuild` = 70450 WHERE `ID` = 90902 AND `locale` = 'ruRU' AND (NOT (CAST(`RewardText` AS BINARY) <=> CAST('Тем, кто пережил смерть, боль не в новинку, и поэтому Отрекшиеся к ней особенно устойчивы. Боль также очищает – пусть она станет для тебя знаком почета и доказательством того, что ты не $gоставил:оставила; служение Свету, несмотря на нынешние обстоятельства.\r\n\r\nБереги себя и следуй путем Света, паладин.' AS BINARY)));
UPDATE `quest_offer_reward_locale` SET `RewardText` = 'К сожалению, немало наших братьев и сестер теряют рассудок схожим образом, когда восстают из мертвых. Каждый Отрекшийся бесценен, но иногда нам не остается иного выхода, кроме как подарить покой тем, кто не может адаптироваться к новой жизни.\r\n\r\nЯ помолюсь Свету за нее. Спасибо, $n. Это было необходимо.', `VerifiedBuild` = 70450 WHERE `ID` = 91208 AND `locale` = 'ruRU' AND (NOT (CAST(`RewardText` AS BINARY) <=> CAST('К сожалению, немало наших братьев и сестер теряют рассудок схожим образом, когда восстают из мертвых. Каждый Отрекшийся бесценен, но иногда нам не остается иного выхода, кроме как подарить покой тем, кто не может адаптироваться к новой жизни.\r\n\r\nЯ помолюсь Свету за нее. Спасибо, $n. Это было необходимо.' AS BINARY)));
UPDATE `quest_offer_reward_locale` SET `RewardText` = 'Добро пожаловать, |3-6($c). Всегда приятно видеть пополнение в наших рядах. Многие в Брилле нуждаются в помощи искателей приключений вроде тебя. Поищи работу и стань сильнее в Свете. А как понадобится чему-то обучиться, возвращайся ко мне.\r\n\r\nКогда проявишь себя передо мной и жителями Брилла, я поведаю тебе, как перейти на следующий этап твоего путешествия.\r\n\r\nДа направит тебя Свет, |3-6($c).', `VerifiedBuild` = 70450 WHERE `ID` = 91209 AND `locale` = 'ruRU' AND (NOT (CAST(`RewardText` AS BINARY) <=> CAST('Добро пожаловать, |3-6($c). Всегда приятно видеть пополнение в наших рядах. Многие в Брилле нуждаются в помощи искателей приключений вроде тебя. Поищи работу и стань сильнее в Свете. А как понадобится чему-то обучиться, возвращайся ко мне.\r\n\r\nКогда проявишь себя передо мной и жителями Брилла, я поведаю тебе, как перейти на следующий этап твоего путешествия.\r\n\r\nДа направит тебя Свет, |3-6($c).' AS BINARY)));
UPDATE `quest_offer_reward_locale` SET `RewardText` = 'Я не с Алым орденом, если ты еще не $gдогадался:догадалась;. Я простая искательница приключений, которая ненадолго остановилась тут перед следующим путешествием в дикие края.\r\n\r\nА ты на вид $gтакой же искатель:такая же искательница; приключений, как я. Не хочешь поучиться премудростям походной жизни?', `VerifiedBuild` = 70450 WHERE `ID` = 96656 AND `locale` = 'ruRU' AND (NOT (CAST(`RewardText` AS BINARY) <=> CAST('Я не с Алым орденом, если ты еще не $gдогадался:догадалась;. Я простая искательница приключений, которая ненадолго остановилась тут перед следующим путешествием в дикие края.\r\n\r\nА ты на вид $gтакой же искатель:такая же искательница; приключений, как я. Не хочешь поучиться премудростям походной жизни?' AS BINARY)));
UPDATE `quest_offer_reward_locale` SET `RewardText` = 'С этим ты сможешь разбить лагерь где угодно. Пока ты $gосвоил:освоила; только азы, так что особенно обставить лагерь не получится.\r\n\r\nУчись – и со временем научишься разжигать огонь пожарче и делать разные интересные вещи.\r\n\r\nЕще ты можешь научиться создавать разные полезные вещи в лагере – поговори с другими наставниками профессий, в которых хоть немного разбираешься.', `VerifiedBuild` = 70450 WHERE `ID` = 96658 AND `locale` = 'ruRU' AND (NOT (CAST(`RewardText` AS BINARY) <=> CAST('С этим ты сможешь разбить лагерь где угодно. Пока ты $gосвоил:освоила; только азы, так что особенно обставить лагерь не получится.\r\n\r\nУчись – и со временем научишься разжигать огонь пожарче и делать разные интересные вещи.\r\n\r\nЕще ты можешь научиться создавать разные полезные вещи в лагере – поговори с другими наставниками профессий, в которых хоть немного разбираешься.' AS BINARY)));
UPDATE `quest_offer_reward_locale` SET `RewardText` = 'Надеюсь, это поможет палачу Аррену и многим другим понять нашу истинную сущность. Как и в прошлой жизни, мы существуем для того, чтобы служить нашему народу и защищать его с помощью сил, дарованных нам Светом.\r\n\r\nСо временем они поймут, что мы так же важны для планов Темной Госпожи, как и остальные Отрекшиеся.\r\n\r\nДа пребудет с тобой Свет.', `VerifiedBuild` = 70450 WHERE `ID` = 98389 AND `locale` = 'ruRU' AND (NOT (CAST(`RewardText` AS BINARY) <=> CAST('Надеюсь, это поможет палачу Аррену и многим другим понять нашу истинную сущность. Как и в прошлой жизни, мы существуем для того, чтобы служить нашему народу и защищать его с помощью сил, дарованных нам Светом.\r\n\r\nСо временем они поймут, что мы так же важны для планов Темной Госпожи, как и остальные Отрекшиеся.\r\n\r\nДа пребудет с тобой Свет.' AS BINARY)));
