UPDATE `quest_template_locale` SET `LogDescription` = 'Добудьте $1oa |4сухую ветку:сухие ветки:сухих веток; и отнесите Элеанор Шеклтон.', `QuestDescription` = 'Моя соратница Элеанор Шеклтон гордится тем, что путешествует по диким местам, выживая в схватке с непогодой и чудовищами. Она разбила лагерь довольно близко, в холмах к западу. Я помню совет, который она мне однажды дала: \"Когда тебе кажется, что дров уже достаточно, собери в пять раз больше\".\r\n\r\nЕсли у тебя найдется свободное время, можешь собрать дров в эту корзину и отнести в ее лагерь. Уверен, она могла бы поделиться с тобой советами, полезными для странствующего искателя приключений.', `VerifiedBuild` = 70450 WHERE `ID` = 86784 AND `locale` = 'ruRU' AND (NOT (CAST(`LogDescription` AS BINARY) <=> CAST('Добудьте $1oa |4сухую ветку:сухие ветки:сухих веток; и отнесите Элеанор Шеклтон.' AS BINARY)) OR NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Моя соратница Элеанор Шеклтон гордится тем, что путешествует по диким местам, выживая в схватке с непогодой и чудовищами. Она разбила лагерь довольно близко, в холмах к западу. Я помню совет, который она мне однажды дала: \"Когда тебе кажется, что дров уже достаточно, собери в пять раз больше\".\r\n\r\nЕсли у тебя найдется свободное время, можешь собрать дров в эту корзину и отнести в ее лагерь. Уверен, она могла бы поделиться с тобой советами, полезными для странствующего искателя приключений.' AS BINARY)));
UPDATE `quest_template_locale` SET `LogDescription` = 'Исцелите $1oa |4израненного стража:израненных стражей:израненных стражей; смерти способностью \"Свет небес\".', `QuestDescription` = 'Я рад приветствовать в наших рядах еще одного паладина, вернувшегося к жизни после смерти. По мере того, как твоя связь со Светом восстанавливается, ты заметишь, что некоторые способности, в прошлом казавшиеся столь естественными, теперь могут причинять тебе сильную боль. Особенно это касается тех, что позволяют тебе исцелять $gсамого:саму; себя или кого-то еще силой Света.\r\n\r\nКак это ни печально, единственный способ справиться с этими трудностями – набраться терпения. Как и при восстановлении атрофировавшихся мышц, тебе нужно превозмогать боль и закалять плоть, чтобы вернуть утраченные силы.', `VerifiedBuild` = 70450 WHERE `ID` = 90902 AND `locale` = 'ruRU' AND (NOT (CAST(`LogDescription` AS BINARY) <=> CAST('Исцелите $1oa |4израненного стража:израненных стражей:израненных стражей; смерти способностью \"Свет небес\".' AS BINARY)) OR NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Я рад приветствовать в наших рядах еще одного паладина, вернувшегося к жизни после смерти. По мере того, как твоя связь со Светом восстанавливается, ты заметишь, что некоторые способности, в прошлом казавшиеся столь естественными, теперь могут причинять тебе сильную боль. Особенно это касается тех, что позволяют тебе исцелять $gсамого:саму; себя или кого-то еще силой Света.\r\n\r\nКак это ни печально, единственный способ справиться с этими трудностями – набраться терпения. Как и при восстановлении атрофировавшихся мышц, тебе нужно превозмогать боль и закалять плоть, чтобы вернуть утраченные силы.' AS BINARY)));
UPDATE `quest_template_locale` SET `QuestDescription` = 'Не всем нашим братьям-паладинам, вернувшимся к жизни, удается быстро приспособиться к новым условиям. Некоторым трудно смириться с тем, что теперь они в некотором смысле стали тем, с чем боролись всю свою жизнь.\r\n\r\nВ таких случаях достаточно просто проявить к ним доброту и сочувствие. К сожалению, многие поддаются гневу. Найди испуганных паладинов, сбежавших в холмы к западу от этой часовни. Протяни им руку дружбы и помоги вернуться к Свету, если сможешь.', `VerifiedBuild` = 70450 WHERE `ID` = 91208 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Не всем нашим братьям-паладинам, вернувшимся к жизни, удается быстро приспособиться к новым условиям. Некоторым трудно смириться с тем, что теперь они в некотором смысле стали тем, с чем боролись всю свою жизнь.\r\n\r\nВ таких случаях достаточно просто проявить к ним доброту и сочувствие. К сожалению, многие поддаются гневу. Найди испуганных паладинов, сбежавших в холмы к западу от этой часовни. Протяни им руку дружбы и помоги вернуться к Свету, если сможешь.' AS BINARY)));
UPDATE `quest_template_locale` SET `QuestDescription` = 'Лордерон уже не тот, что прежде, но наш дом по-прежнему нужно защищать от всевозможных угроз. Пришло время тебе отправиться дальше и исследовать мир. Отправляйся в город Брилл в центре Тирисфальских лесов и поговори с Шари Стилвелл. Она продолжит твое обучение. \r\n\r\nДам тебе еще последний совет: паладинам опасно в землях Отрекшихся. Многие слуги Темной Госпожи не доверяют нам из-за нашей близости к Свету.', `VerifiedBuild` = 70450 WHERE `ID` = 91209 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Лордерон уже не тот, что прежде, но наш дом по-прежнему нужно защищать от всевозможных угроз. Пришло время тебе отправиться дальше и исследовать мир. Отправляйся в город Брилл в центре Тирисфальских лесов и поговори с Шари Стилвелл. Она продолжит твое обучение. \r\n\r\nДам тебе еще последний совет: паладинам опасно в землях Отрекшихся. Многие слуги Темной Госпожи не доверяют нам из-за нашей близости к Свету.' AS BINARY)));
UPDATE `quest_template_locale` SET `LogDescription` = 'Убейте $1oa |4налетчика:налетчиков:налетчиков; из племени Злобного Плавника и $2oa |4провидца:провидцев:провидцев; из племени Злобного Плавника, а затем вернитесь к Бретону Самуэльсу.', `QuestDescription` = 'Обычно мы радушнее приветствуем новичков, но сейчас совсем не до этого, уж слишком нам досаждают мурлоки.\r\n\r\nРаньше в крепости находилось нерестилище их племени. С тех пор как мы сюда перебрались и изгнали мурлочье отродье, они попили немало нашей крови, но теперь ситуация действительно начинает выходить из-под контроля. Ты, кажется, уже многое $gповидал:повидала;. Поможешь нам отвадить этих вредителей? Они прячутся на утесах вдоль дороги на восток и в лагерях вокруг озера на западе.', `VerifiedBuild` = 70450 WHERE `ID` = 91285 AND `locale` = 'ruRU' AND (NOT (CAST(`LogDescription` AS BINARY) <=> CAST('Убейте $1oa |4налетчика:налетчиков:налетчиков; из племени Злобного Плавника и $2oa |4провидца:провидцев:провидцев; из племени Злобного Плавника, а затем вернитесь к Бретону Самуэльсу.' AS BINARY)) OR NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Обычно мы радушнее приветствуем новичков, но сейчас совсем не до этого, уж слишком нам досаждают мурлоки.\r\n\r\nРаньше в крепости находилось нерестилище их племени. С тех пор как мы сюда перебрались и изгнали мурлочье отродье, они попили немало нашей крови, но теперь ситуация действительно начинает выходить из-под контроля. Ты, кажется, уже многое $gповидал:повидала;. Поможешь нам отвадить этих вредителей? Они прячутся на утесах вдоль дороги на восток и в лагерях вокруг озера на западе.' AS BINARY)));
