UPDATE `quest_template_locale` SET `QuestDescription` = 'На таком расстоянии от Подгорода логистика становится сущим кошмаром, и сейчас мы испытываем огромную нехватку стройматериалов, необходимых для восстановления крепости. Твоя помощь в этом деле пришлась бы очень кстати.\r\n\r\nВ Шепчущем лесу к юго-западу отсюда совсем неподалеку ты найдешь разрушенную деревню Тенедол. В одном из строений должен быть старый погребок в корнях , где хранилась всякая всячина. Наверняка там отыщется что-нибудь полезное. Забери оттуда все, что может пригодиться, и возвращайся к нам.', `VerifiedBuild` = 70450 WHERE `ID` = 91316 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('На таком расстоянии от Подгорода логистика становится сущим кошмаром, и сейчас мы испытываем огромную нехватку стройматериалов, необходимых для восстановления крепости. Твоя помощь в этом деле пришлась бы очень кстати.\r\n\r\nВ Шепчущем лесу к юго-западу отсюда совсем неподалеку ты найдешь разрушенную деревню Тенедол. В одном из строений должен быть старый погребок в корнях , где хранилась всякая всячина. Наверняка там отыщется что-нибудь полезное. Забери оттуда все, что может пригодиться, и возвращайся к нам.' AS BINARY)));
UPDATE `quest_template_locale` SET `QuestDescription` = 'Как ты, возможно, уже $gобратил:обратила; внимание, не все восставшие из мертвых паладины смирились со своей новой формой бытия. Некоторые из них до сих пор одержимы предрассудками из прошлой жизни, и потому проявляют агрессию к своим новым братьям-Отрекшимся.\r\n\r\nК нам с недоверием относятся наши же собратья, которые пока еще слишком хорошо помнят притеснения, творимые живыми во имя Света, и подобные неприятности нам совершенно ни к чему. Группа таких \"Порочных\" обосновалась в Тенедоле, что к юго-западу отсюда. Перебей всех и принеси мне голову их лидера.', `VerifiedBuild` = 70450 WHERE `ID` = 91317 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Как ты, возможно, уже $gобратил:обратила; внимание, не все восставшие из мертвых паладины смирились со своей новой формой бытия. Некоторые из них до сих пор одержимы предрассудками из прошлой жизни, и потому проявляют агрессию к своим новым братьям-Отрекшимся.\r\n\r\nК нам с недоверием относятся наши же собратья, которые пока еще слишком хорошо помнят притеснения, творимые живыми во имя Света, и подобные неприятности нам совершенно ни к чему. Группа таких \"Порочных\" обосновалась в Тенедоле, что к юго-западу отсюда. Перебей всех и принеси мне голову их лидера.' AS BINARY)));
UPDATE `quest_template_locale` SET `QuestDescription` = 'Я бы не осмелился усомниться в эффективности формул аптекаря Ренферрела, однако покривил бы душой, если бы сказал, что зелье заметно мне помогло.\r\n\r\nНа берегу озера Лордамер живет стая мурлоков, и, что немаловажно, у них есть глаза. Подозреваю, что готовность аптекаря пробовать что-то новое подавляется его нынешней одержимостью сердцами. Принеси ему несколько глаз этих мурлоков.\r\n\r\nЕсли мне приходится выбирать между неизбежной второй смертью и перспективой пасть от руки Ренферрела за то, что я ставлю под сомнение его профессионализм, то я выбираю последнее.', `VerifiedBuild` = 70450 WHERE `ID` = 91920 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Я бы не осмелился усомниться в эффективности формул аптекаря Ренферрела, однако покривил бы душой, если бы сказал, что зелье заметно мне помогло.\r\n\r\nНа берегу озера Лордамер живет стая мурлоков, и, что немаловажно, у них есть глаза. Подозреваю, что готовность аптекаря пробовать что-то новое подавляется его нынешней одержимостью сердцами. Принеси ему несколько глаз этих мурлоков.\r\n\r\nЕсли мне приходится выбирать между неизбежной второй смертью и перспективой пасть от руки Ренферрела за то, что я ставлю под сомнение его профессионализм, то я выбираю последнее.' AS BINARY)));
UPDATE `quest_template_locale` SET `QuestDescription` = 'А вот и ты! Без сомнения, $gполон:полна; энтузиазма и $gготов:готова; к приключениям! Добро пожаловать в деревню Тендал, нам тут очень нужна помощь. Наверняка ты $gвесь:вся; дрожишь от предвкушения. В конце концов, совершеннолетие бывает лишь раз в жизни.\r\n\r\nСтупай, найди предводителя нашей деревни Рориана Искателя Утра на пути к старому дереву. Это к западу отсюда. Он поможет тебе начать путешествие.', `VerifiedBuild` = 70450 WHERE `ID` = 92460 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('А вот и ты! Без сомнения, $gполон:полна; энтузиазма и $gготов:готова; к приключениям! Добро пожаловать в деревню Тендал, нам тут очень нужна помощь. Наверняка ты $gвесь:вся; дрожишь от предвкушения. В конце концов, совершеннолетие бывает лишь раз в жизни.\r\n\r\nСтупай, найди предводителя нашей деревни Рориана Искателя Утра на пути к старому дереву. Это к западу отсюда. Он поможет тебе начать путешествие.' AS BINARY)));
UPDATE `quest_template_locale` SET `QuestDescription` = 'Рориан наверняка сказал, что я за тобой наблюдаю. Так вот теперь я предлагаю тебе проверку на твердость. Только имей в виду, дело предстоит опасное.\r\n\r\nОтправляйся в пещеры на западе. Прореди стаю медвер и отыщи их матриарха. Следопыты зовут ее Урс\'ана. Расправься с ней и принеси доказательство того, что она мертва. Это будет важный шаг на твоем пути.', `VerifiedBuild` = 70450 WHERE `ID` = 92470 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Рориан наверняка сказал, что я за тобой наблюдаю. Так вот теперь я предлагаю тебе проверку на твердость. Только имей в виду, дело предстоит опасное.\r\n\r\nОтправляйся в пещеры на западе. Прореди стаю медвер и отыщи их матриарха. Следопыты зовут ее Урс\'ана. Расправься с ней и принеси доказательство того, что она мертва. Это будет важный шаг на твоем пути.' AS BINARY)));
UPDATE `quest_template_locale` SET `QuestDescription` = 'Одна из самых давних угроз острова Зефрис – культ Ал\'акет. Это религиозные фанатики, преданные Ал\'акиру Владыке Ветра, который якобы должен править Небесной высью. Они жестоки и упрямы, а их сила и амбиции становятся все опаснее с каждым днем.\r\n\r\nСкоро ты отправишься в деревню Шен\'дар к югу отсюда. Поговори с констеблем Аондой, когда прибудешь туда. Секта угрожает Шен\'дару, и деревне нужна помощь. Скажи Аонде, что ты от меня.', `VerifiedBuild` = 70450 WHERE `ID` = 92472 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Одна из самых давних угроз острова Зефрис – культ Ал\'акет. Это религиозные фанатики, преданные Ал\'акиру Владыке Ветра, который якобы должен править Небесной высью. Они жестоки и упрямы, а их сила и амбиции становятся все опаснее с каждым днем.\r\n\r\nСкоро ты отправишься в деревню Шен\'дар к югу отсюда. Поговори с констеблем Аондой, когда прибудешь туда. Секта угрожает Шен\'дару, и деревне нужна помощь. Скажи Аонде, что ты от меня.' AS BINARY)));
UPDATE `quest_template_locale` SET `QuestDescription` = 'О нет... вот это я попал!\r\n\r\nМне рассказали, что в Западном крае на полях бесчинствуют големы, так что я прибыл сюда аж из самого Стальгорна, чтобы попробовать их перенастроить. Но они оказались куда агрессивнее, чем предсказывали мои расчеты. Даже загнали меня вот в эту конюшню!\r\n\r\nБудь у меня изопружины и гиростабилизаторы големов, я бы собрал устройство, которое поможет скрыться. Соберешь для меня запчасти?', `VerifiedBuild` = 70450 WHERE `ID` = 92909 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('О нет... вот это я попал!\r\n\r\nМне рассказали, что в Западном крае на полях бесчинствуют големы, так что я прибыл сюда аж из самого Стальгорна, чтобы попробовать их перенастроить. Но они оказались куда агрессивнее, чем предсказывали мои расчеты. Даже загнали меня вот в эту конюшню!\r\n\r\nБудь у меня изопружины и гиростабилизаторы големов, я бы собрал устройство, которое поможет скрыться. Соберешь для меня запчасти?' AS BINARY)));
UPDATE `quest_template_locale` SET `QuestDescription` = 'Ветрокамни – важный ресурс здесь, на Зефрисе, так что мы всегда держим у себя запасы для экстренных случаев. Не так давно я заметила, что некоторая часть наших запасов пропала.\r\n\r\nМы нашли ветрокамни у бандитов, которых недавно поймали. Подозреваю, что они-то и стоят за кражей.\r\n\r\nЕсли будешь проходить мимо пещеры бандитов к северу отсюда, может, расшибешь пару лбов и заберешь украденные ветрокамни?', `VerifiedBuild` = 70450 WHERE `ID` = 93319 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Ветрокамни – важный ресурс здесь, на Зефрисе, так что мы всегда держим у себя запасы для экстренных случаев. Не так давно я заметила, что некоторая часть наших запасов пропала.\r\n\r\nМы нашли ветрокамни у бандитов, которых недавно поймали. Подозреваю, что они-то и стоят за кражей.\r\n\r\nЕсли будешь проходить мимо пещеры бандитов к северу отсюда, может, расшибешь пару лбов и заберешь украденные ветрокамни?' AS BINARY)));
UPDATE `quest_template_locale` SET `QuestDescription` = 'Ветрокамень – важнейший ресурс на острове Зефрис, так как он содержит концентрированную энергию ветров. Духи ветра, когда-то жившие здесь с нами, исчезли несколько лет назад, и с тех пор магия, поддерживавшая жизнь на острове, медленно угасает. Ветрокамень – не идеальный, но надежный источник энергии, так что мы его очень ценим.\r\n\r\nКуски ветрокамня разбросаны по роще. Поможешь мне их собрать?', `VerifiedBuild` = 70450 WHERE `ID` = 93552 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Ветрокамень – важнейший ресурс на острове Зефрис, так как он содержит концентрированную энергию ветров. Духи ветра, когда-то жившие здесь с нами, исчезли несколько лет назад, и с тех пор магия, поддерживавшая жизнь на острове, медленно угасает. Ветрокамень – не идеальный, но надежный источник энергии, так что мы его очень ценим.\r\n\r\nКуски ветрокамня разбросаны по роще. Поможешь мне их собрать?' AS BINARY)));
