UPDATE `quest_template_locale` SET `LogDescription` = 'Соберите $1oa |4осколок:осколка;осколков; некротического кристалла в Тирисфальских лесах.', `QuestDescription` = 'Еще не так давно этому городу угрожала цитадель Наксрамас, стремившаяся стереть Отрекшихся с лица земли. И Отрекшиеся, и Серебряный Рассвет тогда принесли огромные жертвы, чтобы обеспечить Отрекшимся будущее.\r\n\r\nВ той битве фокусирующий кристалл некротической энергии, водруженный на вершину Наксрамаса, был разбит, а его осколки разбросаны по округе. Полагаю, они-то и были нужны сектантам. Помоги мне вернуть эти фрагменты, вырвав их из рук Плети.', `VerifiedBuild` = 70450 WHERE `ID` = 96898 AND `locale` = 'ruRU' AND (NOT (CAST(`LogDescription` AS BINARY) <=> CAST('Соберите $1oa |4осколок:осколка;осколков; некротического кристалла в Тирисфальских лесах.' AS BINARY)) OR NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Еще не так давно этому городу угрожала цитадель Наксрамас, стремившаяся стереть Отрекшихся с лица земли. И Отрекшиеся, и Серебряный Рассвет тогда принесли огромные жертвы, чтобы обеспечить Отрекшимся будущее.\r\n\r\nВ той битве фокусирующий кристалл некротической энергии, водруженный на вершину Наксрамаса, был разбит, а его осколки разбросаны по округе. Полагаю, они-то и были нужны сектантам. Помоги мне вернуть эти фрагменты, вырвав их из рук Плети.' AS BINARY)));
UPDATE `quest_template_locale` SET `LogDescription` = 'Принесите Шелене Робарт $1oa |4мембрану:мембраны:мембран; крыла сумеречницы, $2oa |4шкуру:шкуры:шкур; пса тьмы и $3oa |4кусок:куска:кусков; кожи мурлока из племени Злобного Плавника.', `QuestDescription` = 'Одна из особенностей жизни после смерти, о которой никто не упоминает, – это то, что происходит, когда мы получаем ранения. Как заживает кожа у нежити?\r\n\r\nДа никак.\r\n\r\nВся наша жизнь – проклятие, $n. Мы продлеваем свое существование, отнимая у живых.\r\n\r\nКогда мы получаем ранение, кожу приходится заменять, для чего обычно используются шкуры животных. Поскольку шкуры разной толщины лучше подходят для определенных участков на теле, ключ к успеху – разнообразие!\r\n\r\nПринеси мне перепонки крыльев сумеречницы, шкуры псов тьмы и кожу мурлока из племени Злобного Плавника.', `VerifiedBuild` = 70450 WHERE `ID` = 97558 AND `locale` = 'ruRU' AND (NOT (CAST(`LogDescription` AS BINARY) <=> CAST('Принесите Шелене Робарт $1oa |4мембрану:мембраны:мембран; крыла сумеречницы, $2oa |4шкуру:шкуры:шкур; пса тьмы и $3oa |4кусок:куска:кусков; кожи мурлока из племени Злобного Плавника.' AS BINARY)) OR NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Одна из особенностей жизни после смерти, о которой никто не упоминает, – это то, что происходит, когда мы получаем ранения. Как заживает кожа у нежити?\r\n\r\nДа никак.\r\n\r\nВся наша жизнь – проклятие, $n. Мы продлеваем свое существование, отнимая у живых.\r\n\r\nКогда мы получаем ранение, кожу приходится заменять, для чего обычно используются шкуры животных. Поскольку шкуры разной толщины лучше подходят для определенных участков на теле, ключ к успеху – разнообразие!\r\n\r\nПринеси мне перепонки крыльев сумеречницы, шкуры псов тьмы и кожу мурлока из племени Злобного Плавника.' AS BINARY)));
UPDATE `quest_template_locale` SET `LogDescription` = 'Освободите $1oa |4жертву:жертвы:жертв; в паутине в низине Ночных Пут по просьбе Арамиса Хаммерхенда, находящегося в Похоронном Звоне.', `QuestDescription` = 'Приветствую, |3-6($c). Да, я паладин. Даже смерть не остановит Свет.\r\n\r\nВ этом мы едины со всеми Отрекшимися – нам удалось преодолеть то, что живые считают окончанием своей истории. Однако даже многие наши соплеменники страшатся нас. Они думают, будто мы уничтожим их как каких-то чудовищ.\r\n\r\nНа самом же деле наши отношения с посмертием весьма сложны, но причинять вред своим я не собираюсь. Помоги мне доказать это остальным. Отправляйся в низину Ночных Пут к северо-востоку и освободи тех недавно поднявшихся дурней, что оказались там в плену у пауков.', `VerifiedBuild` = 70450 WHERE `ID` = 98389 AND `locale` = 'ruRU' AND (NOT (CAST(`LogDescription` AS BINARY) <=> CAST('Освободите $1oa |4жертву:жертвы:жертв; в паутине в низине Ночных Пут по просьбе Арамиса Хаммерхенда, находящегося в Похоронном Звоне.' AS BINARY)) OR NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Приветствую, |3-6($c). Да, я паладин. Даже смерть не остановит Свет.\r\n\r\nВ этом мы едины со всеми Отрекшимися – нам удалось преодолеть то, что живые считают окончанием своей истории. Однако даже многие наши соплеменники страшатся нас. Они думают, будто мы уничтожим их как каких-то чудовищ.\r\n\r\nНа самом же деле наши отношения с посмертием весьма сложны, но причинять вред своим я не собираюсь. Помоги мне доказать это остальным. Отправляйся в низину Ночных Пут к северо-востоку и освободи тех недавно поднявшихся дурней, что оказались там в плену у пауков.' AS BINARY)));
