UPDATE `quest_template_locale` SET `QuestDescription` = 'Запомни, |3-6($c), Темная Госпожа требует неукоснительного выполнения своих приказов. И, как палач, я обязан за этим следить.\r\n\r\nДонесения от нескольких моих стражей смерти запаздывают. Излишне говорить, что мое терпение лопнуло. Забери у них донесения и принеси мне – именем Темной Госпожи.\r\n\r\nСтража смерти Диллинджера ты найдешь чуть западнее, у кладбища. Страж смерти Кристоф стоит на постое у путевой станции на востоке. И проведай поганище Гордо – он бродит на западе, у Тихого омута.', `VerifiedBuild` = 70450 WHERE `ID` = 99141 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Запомни, |3-6($c), Темная Госпожа требует неукоснительного выполнения своих приказов. И, как палач, я обязан за этим следить.\r\n\r\nДонесения от нескольких моих стражей смерти запаздывают. Излишне говорить, что мое терпение лопнуло. Забери у них донесения и принеси мне – именем Темной Госпожи.\r\n\r\nСтража смерти Диллинджера ты найдешь чуть западнее, у кладбища. Страж смерти Кристоф стоит на постое у путевой станции на востоке. И проведай поганище Гордо – он бродит на западе, у Тихого омута.' AS BINARY)));
UPDATE `quest_template_locale` SET `LogDescription` = 'Соберите $1oa |4пучок:пучка:пучков; гроб-травы по просьбе младшего аптекаря Холланда.', `QuestDescription` = 'Если ты направляешься на восток, к усадьбе Балнира, у меня есть для тебя еще дело. Хороших помощников нынче днем с огнем не сыщешь – твоя встреча с Гордо это наглядно показала.\r\n\r\nЯ вношу в погибельник кое-какие алхимические изменения и пересаживаю на той усадьбе – работа всей моей смерти. Я называю этот сорт гроб-травой, и он приведет меня к тому, что предначертано мне судьбой.\r\n\r\nПока ты там, присмотри-ка за Плетью. Ее словно... тянет... к этой траве. Любопытно.', `VerifiedBuild` = 70450 WHERE `ID` = 99142 AND `locale` = 'ruRU' AND (NOT (CAST(`LogDescription` AS BINARY) <=> CAST('Соберите $1oa |4пучок:пучка:пучков; гроб-травы по просьбе младшего аптекаря Холланда.' AS BINARY)) OR NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Если ты направляешься на восток, к усадьбе Балнира, у меня есть для тебя еще дело. Хороших помощников нынче днем с огнем не сыщешь – твоя встреча с Гордо это наглядно показала.\r\n\r\nЯ вношу в погибельник кое-какие алхимические изменения и пересаживаю на той усадьбе – работа всей моей смерти. Я называю этот сорт гроб-травой, и он приведет меня к тому, что предначертано мне судьбой.\r\n\r\nПока ты там, присмотри-ка за Плетью. Ее словно... тянет... к этой траве. Любопытно.' AS BINARY)));
UPDATE `quest_template_locale` SET `QuestDescription` = 'Хвала Свету за то, что ты меня $gнашел:нашла;. Я направлялся из крепости Бандариона в Брилл с посланием для Шари Стилвелл, когда меня схватили эти чудовища. Они обращаются к Свету с такой ненавистью в сердцах, что даже остатки моей крови закипают. Это противоречит всему, ради чего я предаюсь медитации... всему, что я стремлюсь защитить!\r\n\r\n<Барет Рассветная Скала собирается с силами.>\r\n\r\nЗнаю, кое-кто до сих пор недолюбливает таких, как я, но заверяю тебя: наши намерения чисты. Если поможешь мне выбраться отсюда, я буду вечно тебе благодарен.', `AreaDescription` = 'Выведите Барета Рассветная Скала с заставы Алого ордена.', `VerifiedBuild` = 70450 WHERE `ID` = 99144 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Хвала Свету за то, что ты меня $gнашел:нашла;. Я направлялся из крепости Бандариона в Брилл с посланием для Шари Стилвелл, когда меня схватили эти чудовища. Они обращаются к Свету с такой ненавистью в сердцах, что даже остатки моей крови закипают. Это противоречит всему, ради чего я предаюсь медитации... всему, что я стремлюсь защитить!\r\n\r\n<Барет Рассветная Скала собирается с силами.>\r\n\r\nЗнаю, кое-кто до сих пор недолюбливает таких, как я, но заверяю тебя: наши намерения чисты. Если поможешь мне выбраться отсюда, я буду вечно тебе благодарен.' AS BINARY)) OR NOT (CAST(`AreaDescription` AS BINARY) <=> CAST('Выведите Барета Рассветная Скала с заставы Алого ордена.' AS BINARY)));
